<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";

type Row = Record<string, any>;
const bindings = ref<Row[]>([]); const files = ref<Row[]>([]); const selectedBindingId = ref("");
const sourceItemId = ref(""); const state = ref("DISCOVERED"); const contentFingerprint = ref("");
const failuresOnly = ref(false); const loading = ref(false); const saving = ref(false); const scanning = ref(false); const uploading = ref("");
const error = ref(""); const message = ref(""); const selectedPhotos = ref<File[]>([]); const scannedPhotos = ref<Row[]>([]); const providers = ref<Row[]>([]);
const selectedBinding = computed(() => bindings.value.find(item => String(item.id) === selectedBindingId.value));
function detail(value: any, fallback: string) { return value?.response?.data?.detail || value?.message || fallback; }
function sourceId(file: File) { return `${file.name}:${file.size}:${file.lastModified}`; }
function asHex(buffer: ArrayBuffer) { return Array.from(new Uint8Array(buffer)).map(value => value.toString(16).padStart(2, "0")).join(""); }
async function fingerprint(file: File) { return asHex(await crypto.subtle.digest("SHA-256", await file.arrayBuffer())); }
async function loadBindings() { try { const result = await http.get<unknown, unknown>("/drive/bindings"); bindings.value = Array.isArray(result) ? (result as Row[]).filter(item => item.mode === "BACKUP") : []; if (!selectedBindingId.value && bindings.value[0]?.id) selectedBindingId.value = String(bindings.value[0].id); } catch (e: any) { error.value = detail(e, "备份配置加载失败"); } }
async function loadFiles() { if (!selectedBindingId.value) { files.value = []; return; } loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>(`/drive/bindings/${selectedBindingId.value}/camera-backups`, { params: { failuresOnly: failuresOnly.value } }); files.value = Array.isArray(result) ? result as Row[] : []; } catch (e: any) { error.value = detail(e, "备份检测结果加载失败"); } finally { loading.value = false; } }
async function refreshBinding() { await loadBindings(); await loadFiles(); }
function choosePhotos(event: Event) { selectedPhotos.value = Array.from((event.target as HTMLInputElement).files || []).filter(file => file.type.startsWith("image/")); scannedPhotos.value = []; }
async function scanNewPhotos() { if (!selectedBindingId.value || !selectedPhotos.value.length) { error.value = "请选择备份配置和至少一张照片"; return; } scanning.value = true; error.value = ""; message.value = ""; try { const items = await Promise.all(selectedPhotos.value.map(async file => ({ sourceItemId: sourceId(file), contentFingerprint: await fingerprint(file) }))); const result: any = await http.post(`/drive/bindings/${selectedBindingId.value}/camera-backups/scan`, { data: { items } }); const discovered = Array.isArray(result?.discovered) ? result.discovered : []; const known = Array.isArray(result?.known) ? result.known : []; const knownBySource = new Map(known.map((item: Row) => [String(item.sourceItemId), String(item.contentFingerprint || "")])); scannedPhotos.value = selectedPhotos.value.map(file => { const id = sourceId(file); const digest = items.find(item => item.sourceItemId === id)?.contentFingerprint || ""; return { file, sourceItemId: id, contentFingerprint: digest, state: knownBySource.get(id) === digest ? "已登记，跳过" : discovered.some((item: Row) => item.sourceItemId === id) ? "待上传" : "未新增" }; }); message.value = `扫描完成：发现 ${discovered.length} 张新增或已修改照片，已跳过 ${known.filter((item: Row) => knownBySource.get(String(item.sourceItemId)) === String(item.contentFingerprint || "")).length} 张相同指纹照片。`; } catch (e: any) { error.value = detail(e, "新增照片扫描失败"); } finally { scanning.value = false; } }
async function loadProvider() { try { const result = await http.get<unknown, unknown>("/storage/providers"); providers.value = Array.isArray(result) ? result as Row[] : []; } catch { providers.value = []; } }
async function uploadToProvider(intent: Row, file: File) { if (intent.deduplicated) return; const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer()); const response = await fetch(intent.url, { method: intent.method || "PUT", headers: { "Content-Type": file.type || "application/octet-stream", "x-amz-checksum-sha256": btoa(String.fromCharCode(...new Uint8Array(digest))) }, body: file }); if (!response.ok) throw new Error(`照片上传失败（HTTP ${response.status}）`); }
async function backupPhoto(row: Row) { if (!selectedBinding.value || row.state !== "待上传") return; const file = row.file as File; uploading.value = row.sourceItemId; error.value = ""; message.value = ""; try { const reservation: any = await http.request("put", `/drive/bindings/${selectedBindingId.value}/camera-backups`, { data: { sourceItemId: row.sourceItemId, state: "QUEUED", contentFingerprint: row.contentFingerprint } }); if (reservation?.deduplicated) { row.state = "已跳过重复上传"; message.value = `${file.name} 检测到相同内容指纹，已跳过重复上传。`; await loadFiles(); return; } const resource: any = await http.post("/resources", { headers: { "Idempotency-Key": crypto.randomUUID() }, data: { type: "PHOTO", title: file.name, locale: "zh-CN" } }); const provider = providers.value.find(item => String(item.status).toUpperCase() === "ENABLED")?.providerKey; if (!provider) throw new Error("没有可用的存储 Provider"); const intent: any = await http.post(`/resources/${resource.id}/attachments/upload-intents`, { headers: { "Idempotency-Key": crypto.randomUUID() }, data: { fileName: file.name, sizeBytes: file.size, mediaType: file.type || "image/jpeg", provider, sha256: row.contentFingerprint } }); await uploadToProvider(intent, file); const attachment: any = await http.post(`/resources/${resource.id}/attachments/commit`, { data: { sha256: row.contentFingerprint, uploadSha256: intent.sha256 || row.contentFingerprint, deduplicated: Boolean(intent.deduplicated), sizeBytes: file.size, mediaType: file.type || "application/octet-stream", fileName: file.name, kind: "ORIGINAL", provider: intent.provider, tier: intent.tier, objectKey: intent.objectKey, idempotencyKey: crypto.randomUUID() } }); const photo: any = await http.post("/photos", { data: { title: file.name, attachmentId: attachment.id, locale: "zh-CN" } }); await http.request("put", `/photos/${photo.id}/metadata`, { data: { captureTime: new Date(file.lastModified).toISOString() } }); const node: any = await http.post(`/drive/spaces/${selectedBinding.value.driveSpaceId}/nodes`, { data: { nodeType: "FILE", name: file.name, parentId: selectedBinding.value.remoteRootNodeId } }); const revision: any = await http.post(`/drive/nodes/${node.id}/revisions`, { data: { attachmentId: attachment.id, expectedNodeVersion: node.nodeVersion, contentFingerprint: row.contentFingerprint, operationId: row.sourceItemId } }); await http.request("put", `/drive/bindings/${selectedBindingId.value}/camera-backups`, { data: { sourceItemId: row.sourceItemId, state: "BACKUP_VERIFIED", remoteNodeId: node.id, remoteRevisionId: revision.id, contentFingerprint: row.contentFingerprint } }); row.state = "已备份"; row.photoId = photo.id; message.value = `${file.name} 已上传、登记 Photo 元数据并完成远端备份。`; await loadFiles(); } catch (e: any) { row.state = "失败"; error.value = detail(e, `${file.name} 备份失败`); await http.request("put", `/drive/bindings/${selectedBindingId.value}/camera-backups`, { data: { sourceItemId: row.sourceItemId, state: "ERROR", contentFingerprint: row.contentFingerprint, errorMessage: error.value } }).catch(() => undefined); } finally { uploading.value = ""; } }
async function recordFile() { if (!selectedBindingId.value || !sourceItemId.value.trim()) { error.value = "请选择备份配置并填写本地文件标识"; return; } saving.value = true; error.value = ""; message.value = ""; try { const result: any = await http.request("put", `/drive/bindings/${selectedBindingId.value}/camera-backups`, { data: { sourceItemId: sourceItemId.value.trim(), state: state.value, contentFingerprint: contentFingerprint.value.trim() || undefined } }); sourceItemId.value = ""; contentFingerprint.value = ""; message.value = result?.deduplicated ? "检测到相同内容指纹，已跳过重复上传" : "文件检测结果已保存"; await loadFiles(); } catch (e: any) { error.value = detail(e, "文件检测结果保存失败"); } finally { saving.value = false; } }
onMounted(async () => { await Promise.all([loadBindings(), loadProvider()]); await loadFiles(); });
</script>
<template>
  <main class="p-4 md:p-6"><div class="flex items-start justify-between gap-4 mb-6"><div><h1 class="text-2xl font-semibold">备份文件检测</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">扫描相机胶卷中的新增照片，上传到 Attachment/Photo，并登记到 Drive 备份。</p></div><el-button :loading="loading" @click="refreshBinding">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4" /><el-alert v-if="message" :title="message" type="success" show-icon :closable="false" class="mb-4" />
    <el-card shadow="never" class="mb-4"><template #header><span>扫描并备份新增照片</span></template><div class="flex flex-wrap gap-3 items-center"><el-select v-model="selectedBindingId" placeholder="选择备份配置" class="w-96" @change="loadFiles"><el-option v-for="binding in bindings" :key="binding.id" :label="`${binding.localDisplayPath || binding.localScopeId} → ${binding.driveSpaceId}`" :value="binding.id" /></el-select><input type="file" accept="image/*" multiple @change="choosePhotos" /><el-button type="primary" :loading="scanning" @click="scanNewPhotos">扫描新增照片</el-button></div><div v-if="scannedPhotos.length" class="mt-4"><el-table :data="scannedPhotos" stripe><el-table-column label="照片" min-width="240"><template #default="scope">{{ scope.row.file.name }}</template></el-table-column><el-table-column prop="state" label="扫描结果" width="140" /><el-table-column label="操作" width="140"><template #default="scope"><el-button v-if="scope.row.state === '待上传'" size="small" type="primary" :loading="uploading === scope.row.sourceItemId" @click="backupPhoto(scope.row)">上传并登记</el-button></template></el-table-column></el-table></div></el-card>
    <el-card shadow="never" class="mb-4"><template #header><span>手工登记检测结果</span></template><div class="flex flex-wrap gap-3 items-end"><el-input v-model="sourceItemId" class="w-72" placeholder="本地文件标识" clearable /><el-select v-model="state" class="w-52"><el-option label="新增（已发现）" value="DISCOVERED" /><el-option label="等待备份" value="QUEUED" /><el-option label="来源不可用" value="SOURCE_UNAVAILABLE" /><el-option label="忽略" value="IGNORED" /></el-select><el-input v-model="contentFingerprint" class="w-72" placeholder="内容指纹" clearable /><el-button type="primary" :loading="saving" @click="recordFile">保存检测结果</el-button></div></el-card>
    <el-card shadow="never"><template #header><div class="flex items-center justify-between"><span>已检测文件</span><el-checkbox v-model="failuresOnly" @change="loadFiles">仅显示失败文件</el-checkbox></div></template><el-skeleton v-if="loading" :rows="5" animated /><el-empty v-else-if="!files.length" :description="failuresOnly ? '暂无失败文件' : '暂无检测记录'" /><el-table v-else :data="files" stripe><el-table-column prop="sourceItemId" label="本地文件标识" min-width="260" /><el-table-column prop="state" label="状态" width="190" /><el-table-column prop="errorMessage" label="失败原因" min-width="260" show-overflow-tooltip /><el-table-column prop="contentFingerprint" label="内容指纹" min-width="220" /><el-table-column prop="remoteNodeId" label="远端节点" min-width="220" /><el-table-column prop="updatedAt" label="更新时间" min-width="190" /></el-table></el-card>
  </main>
</template>
